using System;
using System.Collections.Generic;

namespace PirexZenith
{
    /// <summary>
    /// Stores Ahead-Of-Time (AOT) static constructor factories generated by Unity Editor Code Generator.
    /// Eliminates reflection and warmup costs on target platforms (IL2CPP / AOT).
    /// </summary>
    public static class PirexZenithAOTCache
    {
        private static readonly Dictionary<Type, Func<IResolver, object>> _aotFactories = new Dictionary<Type, Func<IResolver, object>>();
        private static readonly object _lock = new object();

        /// <summary>
        /// Registers a compiled static factory delegate for type T.
        /// </summary>
        public static void Register<T>(Func<IResolver, object> factory)
        {
            if (factory == null) return;
            lock (_lock)
            {
                _aotFactories[typeof(T)] = factory;
            }
        }

        /// <summary>
        /// Attempts to retrieve an AOT compiled factory delegate for the specified Type.
        /// </summary>
        public static bool TryGetFactory(Type type, out Func<IResolver, object> factory)
        {
            lock (_lock)
            {
                return _aotFactories.TryGetValue(type, out factory);
            }
        }

        /// <summary>
        /// Clears all registered AOT factories.
        /// </summary>
        public static void Clear()
        {
            lock (_lock)
            {
                _aotFactories.Clear();
            }
        }
    }
}
